#!/usr/bin/env python3
"""Count lines, words, and characters in text files, like wc."""

import sys


def count_file(filepath):
    with open(filepath, "r") as f:
        content = f.read()
    lines = content.count("\n")
    words = len(content.split())
    chars = len(content)
    return lines, words, chars


def main():
    if len(sys.argv) < 2:
        print(f"Usage: {sys.argv[0]} FILE [FILE ...]", file=sys.stderr)
        sys.exit(1)

    total_lines = total_words = total_chars = 0
    for filepath in sys.argv[1:]:
        try:
            lines, words, chars = count_file(filepath)
            print(f"{lines:7d} {words:7d} {chars:7d} {filepath}")
            total_lines += lines
            total_words += words
            total_chars += chars
        except FileNotFoundError:
            print(f"wc: {filepath}: No such file or directory", file=sys.stderr)
        except IsADirectoryError:
            print(f"wc: {filepath}: Is a directory", file=sys.stderr)

    if len(sys.argv) > 2:
        print(f"{total_lines:7d} {total_words:7d} {total_chars:7d} total")


if __name__ == "__main__":
    main()
